'use strict';
const $=id=>document.getElementById(id);
const labels={golden:'Golden cross',rsi:'RSI reversal',macd:'MACD crossover',obv:'Rising OBV',bollinger:'Bollinger recovery',stochastic:'Stochastic reversal',market:'Market / economic'};
const weights={golden:20,rsi:15,macd:20,obv:15,bollinger:10,stochastic:10,market:10};
let data={stocks:[]},visible=[];
const fmt=n=>Number(n).toLocaleString('en-IN',{maximumFractionDigits:2});
const el=(tag,text,cls)=>{const e=document.createElement(tag);e.textContent=text;if(cls)e.className=cls;return e;};
for(const [key,name]of Object.entries(labels)){const box=el('div');box.append(el('strong',weights[key]+'%'),el('span',name));$('weights').append(box);if(key==='market')continue;const label=el('label',null,'check'),input=document.createElement('input');input.type='checkbox';input.value=key;input.addEventListener('change',render);label.append(input,document.createTextNode(name));$('signal-filters').append(label);}
function filtered(){const q=$('search').value.trim().toLowerCase(),sector=$('sector').value,min=Number($('minimum').value),only=$('strong-only').checked,signals=[...document.querySelectorAll('#signal-filters input:checked')].map(x=>x.value);return data.stocks.filter(r=>r.eligible&&!r.stale&&r.dma50>r.dma200&&r.technicalScore>=min&&(!only||r.stronger)&&(!sector||r.sector===sector)&&(!q||(r.name+' '+r.symbol).toLowerCase().includes(q))&&signals.every(s=>r.scores[s]>0)).sort((a,b)=>b.technicalScore-a.technicalScore||a.symbol.localeCompare(b.symbol));}
function render(){const all=filtered();visible=all.slice(0,Number($('limit').value));$('count').textContent=all.length;$('min-label').textContent=$('minimum').value+' / 90';$('rows').replaceChildren();for(const[ridx,r]of visible.entries()){const tr=el('tr'),name=el('td'),button=el('button',(ridx+1)+'. '+r.symbol,'stock-button');button.append(el('small',r.name));button.onclick=()=>detail(r);name.append(button);const price=el('td','₹'+fmt(r.price));price.append(el('small',(r.change>0?'+':'')+fmt(r.change)+'%',r.change>=0?'positive':'negative'));const score=el('td',fmt(r.technicalScore)+'/90','score');if(r.score!==null)score.append(el('small','Full score '+fmt(r.score)+'/100'));const delta=el('td',r.delta===null?'—':(r.delta>0?'+':'')+r.delta,r.delta>0?'positive':'');const signals=el('td');for(const key of Object.keys(labels))if(key!=='market'&&r.scores[key]>0)signals.append(el('span',key==='golden'?'DMA':key.toUpperCase(), 'chip'));const market=el('td',r.marketComplete?fmt(r.scores.market)+'/10':'Unverified');tr.append(name,price,score,delta,signals,market);$('rows').append(tr);}$('empty').hidden=visible.length>0;if(!visible.length){$('empty').querySelector('h3').textContent=data.stocks.length?'No stocks match these filters':'Your screener is ready for data';$('empty').querySelector('p').textContent=data.stocks.length?'Try reducing the minimum score or removing a signal requirement. The DMA rule stays required.':'Connect the daily market feed to calculate real rankings across the Nifty 500.';$('empty').querySelector('a').hidden=!!data.stocks.length;}}
function detail(r){$('detail-title').textContent=r.name+' · '+r.symbol;const body=$('detail-body');body.replaceChildren(el('p','As of '+r.date+' · ₹'+fmt(r.price)+' · 50 DMA '+fmt(r.dma50)+' / 200 DMA '+fmt(r.dma200)));for(const key of Object.keys(labels)){const line=el('div',null,'detail-line');line.append(el('b',labels[key]+' · '+(key==='market'&&!r.marketComplete?'Unverified':r.scores[key]+'/'+weights[key])),el('span',key==='market'?Object.entries(r.marketFactors||{}).map(([k,v])=>k+': '+(v.positive?'positive':'not positive')+' ('+v.date+') '+v.source).join(' · ')||'No verified market context supplied.':r.notes[key]));body.append(line);}body.append(el('h3','What changed'),el('p',r.delta===null?'First snapshot — no comparison available.':r.changed.length?r.changed.join(' · '):'No improved technical signals since the previous snapshot.'));$('detail').showModal();}
async function load(){const button=$('refresh');button.disabled=true;button.textContent='Refreshing…';try{let res;try{res=await fetch('https://raw.githubusercontent.com/texttotejas-ui/screener/main/dist/data.json',{cache:'no-store',signal:AbortSignal.timeout(12000)});if(!res.ok)throw Error('remote');}catch{res=await fetch('data.json',{cache:'no-store'});}if(!res.ok)throw Error('Unable to load snapshot');const next=await res.json();if(!Array.isArray(next.stocks))throw Error('Invalid snapshot');data=next;const prev=$('sector').value;$('sector').replaceChildren(new Option('All sectors',''));[...new Set(data.stocks.map(r=>r.sector))].sort().forEach(s=>$('sector').add(new Option(s,s)));$('sector').value=prev;$('universe').textContent=data.universeCount||'—';$('analysed').textContent=data.stocks.length||'—';$('qualified').textContent=data.stocks.filter(r=>r.eligible&&!r.stale).length;$('stronger').textContent=data.stocks.filter(r=>r.stronger&&!r.stale).length;$('coverage').textContent=data.stocks.length?(data.errors.length+' unavailable · '+data.stocks.filter(r=>r.stale).length+' stale'):'Waiting for data';const age=data.asOf?(Date.now()-Date.parse(data.asOf+'T15:30:00+05:30'))/86400000:Infinity;$('status').className='notice'+(data.stocks.length&&age<4?' ready':'');$('status').textContent=data.stocks.length?`Latest saved session: ${data.asOf}. ${data.stocks.length}/${data.universeCount} stocks analysed. ${age>=4?'This snapshot is stale. ':''}Market factors are scored only with dated evidence.`:'Market data is not connected yet. No live rankings or sample stock prices are shown. Open Data connection below to activate the daily scan.';$('source').textContent=data.provider;$('asof').textContent=data.asOf?'Daily candles · '+data.asOf+' · '+data.provider:'No market snapshot available';render();}catch(e){$('status').className='notice';$('status').textContent='Could not refresh the snapshot. '+(data.stocks.length?'The previous results remain visible.':'Please try again.');}finally{button.disabled=false;button.textContent='Refresh data ↻';}}
for(const id of ['search','sector','minimum','strong-only','limit'])$(id).addEventListener('input',render);
$('refresh').onclick=load;$('close-detail').onclick=()=>$('detail').close();$('reset').onclick=()=>{$('search').value='';$('sector').value='';$('minimum').value='0';$('strong-only').checked=false;$('limit').value='10';document.querySelectorAll('#signal-filters input').forEach(e=>e.checked=false);render();};
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'filter_stocklist',description:'Filter the visible Stocklist technical ranking. The 50 DMA > 200 DMA gate always applies.',inputSchema:{type:'object',properties:{query:{type:'string'},minimumScore:{type:'number',minimum:0,maximum:90},strongerOnly:{type:'boolean'}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['query','minimumScore','strongerOnly'].includes(k))||('query'in input&&typeof input.query!=='string')||('minimumScore'in input&&(!Number.isFinite(input.minimumScore)||input.minimumScore<0||input.minimumScore>90))||('strongerOnly'in input&&typeof input.strongerOnly!=='boolean'))throw Error('Invalid filter');if(input.query!==undefined)$('search').value=input.query;if(input.minimumScore!==undefined)$('minimum').value=String(input.minimumScore);if(input.strongerOnly!==undefined)$('strong-only').checked=input.strongerOnly;render();return{asOf:data.asOf,matched:filtered().length,stocks:visible.map(r=>({symbol:r.symbol,technicalScore:r.technicalScore}))};}})).catch(()=>{});}catch{}}
load();
